sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
	try {
        var data = request.body.data;

        if (!data || !data.correlation_id) {
            response.setStatus(400);
            return {
                status: 'error',
                message: 'Missing required field: correlation_id'
            };
        }

        // Prevent duplicate creation if a record with this correlation_id already exists
        var existing = new GlideRecord('x_2307388_it_ass_0_asset_request');
        existing.addQuery('correlation_id', data.correlation_id);
        existing.setLimit(1);
        existing.query();

        if (existing.next()) {
            response.setStatus(409);
            return {
                status: 'error',
                message: 'Record already exists. Use PATCH to update.',
                sys_id: existing.getUniqueValue()
            };
        }

        var gr = new GlideRecord('x_2307388_it_ass_0_asset_request');
        gr.initialize();
        gr.setValue('correlation_id', data.correlation_id);

        var fields = [
            'opened_by',
            'requestor',
            'type_of_asset',
            'consumables',
            'company',
            'priority',
            'short_description',
            'description'
        ];

        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            if (data[field] !== undefined && data[field] !== null) {
                gr.setValue(field, data[field]);
            }
        }

        var recordSysId = gr.insert();

        if (!recordSysId) {
            response.setStatus(500);
            return {
                status: 'error',
                message: 'Failed to insert record on target instance.'
            };
        }

        response.setStatus(201);
        return {
            status: 'inserted',
            sys_id: recordSysId,
            number: gr.getValue('number')
        };

    } catch (ex) {
        response.setStatus(500);
        return {
            status: 'error',
            message: ex.getMessage()
        };
    }

})(request, response);
